import React, { useState, useEffect } from "react";
import { useParams, useHistory } from 'react-router-dom';
import Header from "../../components/client/Header"; // Ajuste le chemin si besoin
import "../../styles/addArticle.css"; // On réutilise ton CSS qui marche très bien

function AddService() {
    const { idService } = useParams(); // Permet de savoir si on est en mode "Création" ou "Modification"
    const history = useHistory();
    const [image, setImage] = useState(null);
    const [service, setService] = useState({
        name: '',
        description: '',
        basePrice: 0,
        defaultDuration: 90, // Durée par défaut en minutes
        image: ''
    });

    // Récupération des données si on est en mode Modification
    useEffect(() => {
        if (idService) {
           fetch(`http://localhost:3001/catalog/services/${idService}`)
            .then(response => response.json())
            .then(data => {
                setService({
                    name: data.name,
                    description: data.description,
                    basePrice: data.basePrice,
                    defaultDuration: data.defaultDuration,
                    image: data.image
                });
            })
            .catch(error => {
                console.error('Erreur lors de la récupération de la prestation :', error);
            }); 
        }
    }, [idService]);

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setService(prevState => ({
            ...prevState,
            [name]: value
        }));
    };

    const handleImageChange = (e) => setImage(e.target.files[0]);

    // Fonction d'AJOUT (POST)
    const handleAddService = async () => {
        let finalImageUrl = service.image;
        
        // Upload de l'image (identique à AddArticle)
        if (image) {
            const formData = new FormData();
            formData.append('image', image);
            try {
                const uploadResponse = await fetch('http://localhost:3001/upload', {
                    method: 'POST',
                    body: formData
                });
                const uploadData = await uploadResponse.json();
                finalImageUrl = uploadData.imageUrl || uploadData.image; 
            } catch (error) {
                console.error('Erreur upload image:', error);
                alert("Erreur lors de l'upload de l'image.");
                return; 
            }
        }

        const serviceToSave = { ...service, image: finalImageUrl };

        fetch('http://localhost:3001/catalog/services', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(serviceToSave)
        })
        .then(async response => {
            const data = await response.json();
            if (!response.ok) throw new Error(data.error || 'Erreur serveur');
            
            alert("Prestation ajoutée au catalogue avec succès !");
            history.push('/admin'); // Redirige vers le dashboard ou la page voulue
        })
        .catch(error => {
            console.error('Erreur création prestation : ', error);
            alert('Impossible de créer la prestation : ' + error.message);
        });
    };

    // Fonction de MODIFICATION (PUT)
    const handleChangeService = async () => {
        let finalImageUrl = service.image;
        
        if (image) {
            const formData = new FormData();
            formData.append('image', image);
            try {
                const uploadResponse = await fetch('http://localhost:3001/upload', {
                    method: 'POST',
                    body: formData
                });
                const uploadData = await uploadResponse.json();
                finalImageUrl = uploadData.imageUrl || uploadData.image; 
            } catch (error) {
                console.error('Erreur upload image:', error);
                alert("Erreur lors de l'upload de l'image.");
                return;
            }
        }

        const serviceToSave = { ...service, image: finalImageUrl };

        fetch(`http://localhost:3001/catalog/services/${idService}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(serviceToSave)
        })
        .then(async response => {
            const data = await response.json();
            if (!response.ok) throw new Error(data.error || 'Erreur serveur');
            
            alert("Prestation modifiée avec succès !");
            history.push('/admin'); // Redirige vers le dashboard
        })
        .catch(error => {
            console.error('Erreur modification : ', error);
            alert('Impossible de modifier la prestation : ' + error.message);
        });
    };

    return (
       <div>
        <div className="flex-column" style={{ maxWidth: '800px', margin: '40px auto', padding: '20px', backgroundColor: '#fbfbfb', borderRadius: '8px', border: '1px solid #ccc' }}>
            <h1>Formulaire de {idService ? "modification": "création"} d'une prestation</h1>

            <label style={{ marginTop: '15px', fontWeight: 'bold' }}>Nom de la prestation</label>
            <input type="text" name="name" onChange={handleInputChange} className="detail-input" value={service.name} placeholder="Ex: Cours de Paddle avancé"></input>

            <label style={{ marginTop: '15px', fontWeight: 'bold' }}>Description</label>
            <textarea name="description" onChange={handleInputChange} className="detail-input" value={service.description} rows="4" style={{ resize: 'vertical' }}></textarea>

            <label style={{ marginTop: '15px', fontWeight: 'bold' }}>Prix de base (€)</label>
            <input type="number" name="basePrice" step="0.01" onChange={handleInputChange} className="detail-input" value={service.basePrice}></input>

            <label style={{ marginTop: '15px', fontWeight: 'bold' }}>Durée par défaut (minutes)</label>
            <input type="number" name="defaultDuration" onChange={handleInputChange} className="detail-input" value={service.defaultDuration} placeholder="Ex: 90"></input>

            <label style={{ marginTop: '15px', fontWeight: 'bold' }}>Image d'illustration</label>
            {idService && service.image && <img src={service.image} alt="prestation" style={{width: "200px", borderRadius: '8px', marginBottom: '10px'}}/>}
            <input type="file" name="image" onChange={handleImageChange} className="detail-input"/>

            <div className="center-container" style={{ marginTop: '30px' }}>
                {idService ? 
                <button onClick={handleChangeService} className="button btn-save">Modifier la prestation</button>
                :
                <button onClick={handleAddService} className="button btn-save">Ajouter au catalogue</button>
                }
            </div>
        </div>
    </div> 
    );
} 

export default AddService;
